package md.utm.messaging.consumers;
import md.utm.messaging.contracts.*; import java.io.*; import java.net.*; import java.nio.file.*; import java.time.*;
public final class ConsumerClient { private final String host,consumerId,destination; private final int port; private final ConsumerMode mode; private final DeduplicationStore dedup; private final Path effects;
 public ConsumerClient(String h,int p,String id,String d,ConsumerMode m,Path dataDir)throws IOException{host=h;port=p;consumerId=id;destination=d;mode=m;dedup=new DeduplicationStore(dataDir.resolve("processed-"+id+".txt"));effects=dataDir.resolve("effects-"+id+".log");}
 public void run()throws IOException{try(Socket s=new Socket(host,port);var r=JsonLineProtocol.reader(s.getInputStream());var w=JsonLineProtocol.writer(s.getOutputStream())){JsonLineProtocol.write(w,TransportFrame.register(consumerId,destination));TransportFrame reg=JsonLineProtocol.read(r);if(!"registered".equals(reg.kind()))throw new IOException("Registration rejected");System.out.println("Registered "+consumerId+" -> "+destination+" mode="+mode);while(true){TransportFrame f=JsonLineProtocol.read(r);if(!"delivery".equals(f.kind())||f.message()==null)continue;process(f,w);}}}
 private void process(TransportFrame f,BufferedWriter w)throws IOException{MessageEnvelope m=f.message();StructuredLog.write("INFO","consumer","RECEIVED",m,null,"consumer="+consumerId+" attempt="+f.attempt()); if(dedup.contains(m.id())){StructuredLog.write("INFO","consumer","DUPLICATE",m,"effect-skipped","consumer="+consumerId);JsonLineProtocol.write(w,TransportFrame.ack(m.id()));StructuredLog.write("INFO","consumer","ACK_SENT",m,"success",null);return;} if(mode==ConsumerMode.ALWAYS_NACK){StructuredLog.write("WARN","consumer","PROCESSING_FAILED",m,"simulated",null);JsonLineProtocol.write(w,TransportFrame.nack(m.id(),"Simulated failure"));StructuredLog.write("WARN","consumer","NACK_SENT",m,"retry",null);return;} try{Files.writeString(effects,OffsetDateTime.now(ZoneOffset.UTC)+" | messageId="+m.id()+" | correlationId="+m.correlationId()+" | type="+m.type()+" | payload="+m.payload()+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);dedup.markProcessed(m.id());StructuredLog.write("INFO","consumer","PROCESSED",m,"success",null);if(mode==ConsumerMode.CRASH_BEFORE_ACK){StructuredLog.write("ERROR","consumer","CRASH_BEFORE_ACK",m,"intentional-exit",null);System.exit(17);}JsonLineProtocol.write(w,TransportFrame.ack(m.id()));StructuredLog.write("INFO","consumer","ACK_SENT",m,"success",null);}catch(IOException e){StructuredLog.write("ERROR","consumer","PROCESSING_ERROR",m,"failed","reason="+e.getMessage());JsonLineProtocol.write(w,TransportFrame.nack(m.id(),e.getMessage()));}}
}
